import{_ as e,o as a,c as n,S as o}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"前端开发如何防止逆向以及对策","description":"","frontmatter":{"title":"前端开发如何防止逆向以及对策","date":"2020-02-22 18:03","comments":true,"archives":2020,"tags":["frontend"]},"headers":[],"relativePath":"posts/2020-02-22-hack-dev-tools/index.md","filePath":"posts/2020/2020-02-22-hack-dev-tools.md"}'),l={name:"posts/2020-02-22-hack-dev-tools/index.md"};function t(p,s,r,c,i,d){return a(),n("div",null,[...s[0]||(s[0]=[o(`<p>前端开发分析代码的途径最简单不过了，第一个途径是查看网页源代码，第二个途径是打开开发者工具审查元素。</p><h2 id="防止查看源代码" tabindex="-1">防止查看源代码 <a class="header-anchor" href="#防止查看源代码" aria-label="Permalink to &quot;防止查看源代码&quot;">​</a></h2><p>现在网站的基本对策是禁用用户右键选项菜单来避免查看源代码。首先，源代码肯定是能查看到的。采取的措施也只不过是掩耳盗铃而已。解决对策也有很多，我随便说几个。</p><p>第一，针对 Chrome 浏览器，我们可以直接在地址栏里输入 <code>view-source:https://www.google.com/</code> 这种方式来查看源代码。第二，我们可以使用其他工具，例如<code>curl</code>, <code>wget</code>来直接下载源代码。这种是很初级的防范对策。</p><h2 id="防止审查元素" tabindex="-1">防止审查元素 <a class="header-anchor" href="#防止审查元素" aria-label="Permalink to &quot;防止审查元素&quot;">​</a></h2><p>现代化的前端开发，都是基于 JS 来渲染页面元素的，有时候我们查看源代码也只是看到了 JS 文件的引用。没有太大意义，所以需要浏览器渲染之后查看真正的 DOM 元素才有意义。这时候如何禁止审查元素就是另外一种对策了。 现在用来检测打开开发者工具主要是通过判断<code>console.log</code>的执行，因为不打开开发者工具的话<code>console.log</code>是不会执行的。所以有些网站就可以利用这个来阻止用户打开开发者工具审查元素和 Debug 代码。 下面给出一个例子来：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">let el = new Image();</span></span>
<span class="line"><span style="color:#24292E;">Object.defineProperty(el,&#39;id&#39;,{get: </span><span style="color:#D73A49;">function</span><span style="color:#24292E;">(){window.location.href</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&quot;http://www.bimibimi.tv&quot;</span><span style="color:#24292E;">}});</span></span>
<span class="line"><span style="color:#24292E;">console.log(el);</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这是一个非常巧妙的例子，当执行<code>console.log</code>输出 Image 元素的时候，比如会访问 id 属性，从而触发后面的重定向 URL 代码。所以表现就是用户试图打开开发者面板就会被自动定位到首页。</p><p>要破解这个的话，只能在页面执行之前注入代码修改 Image 函数的使用：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">window.</span><span style="color:#6F42C1;">Image</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> function</span><span style="color:#24292E;"> () {};</span></span>
<span class="line"><span style="color:#24292E;">Object.</span><span style="color:#6F42C1;">defineProperty</span><span style="color:#24292E;">(window, </span><span style="color:#032F62;">&#39;Image&#39;</span><span style="color:#24292E;">, { writable: </span><span style="color:#005CC5;">false</span><span style="color:#24292E;"> });</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>通过注入上面的代码，来规避自动跳转到首页。如何注入呢？ 就需要利用 Chrome 的扩展功能，详细代码请参照<a href="https://github.com/acgotaku/bimibimi-hack" target="_blank" rel="noreferrer">bimibimi-hack</a>。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>前端代码逆向和反逆向，永远没有银弹。只能说是提高逆向的门槛，但想完全防止是不可能的。如果自己编译一个浏览器，修改浏览器的默认行为的话，就没有不能调试的网站。</p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><p><a href="https://stackoverflow.com/questions/7798748/find-out-whether-chrome-console-is-open" target="_blank" rel="noreferrer">Find out whether Chrome console is open</a></p><p><a href="view-source:http://www.bimibimi.tv/bangumi/640/play/1/1/">Source code of bimibimi.tv</a></p>`,16)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
